// interactables.ts — usable props (the Tea House radio, later buttons, switches, ...).
//
// The generalisation of the Tea House door machine's session driver (teaDoor.ts), minus the door-specific
// parts (leaf, blocker, step-through). Definitions come from the room index (generated by tools/city3, see
// kit.add_interactable): they are static data, known before the room streams in, so agents can plan against
// them and the sound layer can play a radio nobody is looking at. Only the MESH depends on streaming.
//
// A session is: align (walk to the stand pose, face the prop) -> perform (the `Interact` clip; the state
// flips at the contact moment) -> done. One session per interactable; an actor owns at most one. The
// controller is pure (no three.js, no DOM): the clip channel and the walker state are injected, so the
// player, Scout and future NPCs all use it the same way (the actor id keys who holds what).
import { clipDef } from "./clips";
import { angleTo, type WalkInput, type WalkerState } from "./walker";
import { alignInput, type StandPose } from "./teaDoor";

/** One usable prop, as the room index lists it (units: m, three.js XZ; heading faces (sin h, cos h)). */
export interface InteractableDef {
  id: string;
  room: string;
  kind: "radio" | (string & {});
  /** Library asset key (LIB_<asset> in world-city3-library.glb). */
  asset: string;
  label: string;
  /** Prop position [x, y, z] (y = the surface it stands on). */
  pos: [number, number, number];
  rotY: number;
  /** Where a walker stands to use it, and the heading that faces the prop. */
  stand: [number, number];
  heading: number;
  floorY: number;
}

/** The clip channel a session fires through: structurally a ClipTestState / WalkClipOverride. */
export interface InteractChannel {
  fire(name: string): boolean;
  readonly current: string | null;
}

export const INTERACT_CLIP = "Interact";
/** Seconds into the Interact clip when the hand meets the prop and the state flips (estimated; see the docs). */
export const INTERACT_CONTACT_S = 1.2;
/** A request is refused beyond this distance (m) from the stand point. */
export const INTERACT_REQUEST_RANGE = 2.5;
/** The prompt shows (and E works) within this distance (m) of the stand point. */
export const INTERACT_PROMPT_RANGE = 2.0;
/** Align gives up after this long (s): never hunt for the pose for ever. */
export const INTERACT_ALIGN_TIMEOUT_S = 8;
/** An actor not driven for this long (s) is gone (walk mode exited, agent unmounted): its session is dropped. */
const ACTOR_TTL = 1.0;

export type InteractPhase = "align" | "perform";
export type InteractResult = "started" | "unknown" | "too-far" | "busy" | "already-using";

interface Session {
  id: string;
  actor: string;
  channel: InteractChannel;
  phase: InteractPhase;
  /** Seconds in the current phase. */
  t: number;
  flipped: boolean;
}

const ZERO_INPUT: WalkInput = { forward: 0, strafe: 0, turn: 0, run: false };

/** Stand pose of a prop (the align target). */
export function interactPose(def: InteractableDef): StandPose {
  return { x: def.stand[0], z: def.stand[1], heading: def.heading };
}

function atPose(s: WalkerState, pose: StandPose): boolean {
  return (
    Math.hypot(s.x - pose.x, s.z - pose.z) <= 0.035 &&
    Math.abs(angleTo(s.heading, pose.heading)) <= 0.03 &&
    Math.abs(angleTo(s.body, pose.heading)) <= 0.06
  );
}

export class InteractController {
  private readonly defs = new Map<string, InteractableDef>();
  private readonly on = new Map<string, boolean>();
  private readonly sessions = new Map<string, Session>();
  private readonly seen = new Map<string, { x: number; z: number; at: number }>();
  private readonly listeners = new Set<(id: string, on: boolean) => void>();
  private readonly contactS: number;
  private readonly durationS: number;
  private now = 0;
  /** Last refusal, for the HUD status line. */
  lastRefusal: { id: string; reason: string; at: number } | null = null;

  constructor(opts: { contactS?: number } = {}) {
    this.contactS = opts.contactS ?? INTERACT_CONTACT_S;
    this.durationS = clipDef(INTERACT_CLIP)?.duration ?? 3.2333;
  }

  /** Replace the known interactables (the room index loaded). State survives for ids that stay. */
  register(defs: readonly InteractableDef[]): void {
    this.defs.clear();
    for (const d of defs) {
      this.defs.set(d.id, d);
      if (!this.on.has(d.id)) this.on.set(d.id, false);
    }
    for (const id of [...this.sessions.keys()]) if (!this.defs.has(id)) this.sessions.delete(id);
  }

  list(): InteractableDef[] {
    return [...this.defs.values()];
  }

  get(id: string): InteractableDef | undefined {
    return this.defs.get(id);
  }

  isOn(id: string): boolean {
    return this.on.get(id) ?? false;
  }

  /** State changes (visual + sound follow). Returns an unsubscribe. */
  subscribe(fn: (id: string, on: boolean) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private setOn(id: string, v: boolean): void {
    if (this.on.get(id) === v) return;
    this.on.set(id, v);
    for (const fn of this.listeners) fn(id, v);
  }

  /** The actor who holds this prop right now, or null. */
  sessionOwner(id: string): string | null {
    return this.sessions.get(id)?.actor ?? null;
  }

  /** The session an actor is in, if any (phase for the HUD / headless checks). */
  sessionOf(actor: string): { id: string; phase: InteractPhase; t: number } | null {
    for (const s of this.sessions.values()) if (s.actor === actor) return { id: s.id, phase: s.phase, t: s.t };
    return null;
  }

  private refuse(id: string, reason: InteractResult): InteractResult {
    this.lastRefusal = { id, reason, at: this.now };
    return reason;
  }

  /** The prop an actor could use right now: nearest stand point within the prompt range, else null. */
  nearest(x: number, z: number, range = INTERACT_PROMPT_RANGE): InteractableDef | null {
    let best: InteractableDef | null = null;
    let bd = Infinity;
    for (const d of this.defs.values()) {
      const dist = Math.hypot(d.stand[0] - x, d.stand[1] - z);
      if (dist <= range && dist < bd) {
        bd = dist;
        best = d;
      }
    }
    return best;
  }

  /** Start a session for `actor` on `id`. The actor's position comes from its last drive() (or `at`). */
  request(id: string, actor: string, channel: InteractChannel, at?: { x: number; z: number }): InteractResult {
    const def = this.defs.get(id);
    if (!def) return this.refuse(id, "unknown");
    if (this.sessionOf(actor)) return this.refuse(id, "already-using");
    if (this.sessions.has(id)) return this.refuse(id, "busy");
    const pos = at ?? this.seen.get(actor);
    if (!pos) return this.refuse(id, "too-far");
    if (Math.hypot(pos.x - def.stand[0], pos.z - def.stand[1]) > INTERACT_REQUEST_RANGE) return this.refuse(id, "too-far");
    this.sessions.set(id, { id, actor, channel, phase: "align", t: 0, flipped: false });
    this.lastRefusal = null;
    return "started";
  }

  /** E key / agent shortcut: use the nearest prop within the prompt range. */
  requestNearest(actor: string, channel: InteractChannel, at: { x: number; z: number }): InteractResult {
    const d = this.nearest(at.x, at.z);
    if (!d) return "too-far";
    return this.request(d.id, actor, channel, at);
  }

  /**
   * Per-frame driver for one actor. Returns the WalkInput to step with while the actor's session holds the body
   * (walk to the stand pose, face the prop, the Interact clip), or null when the actor keeps control.
   */
  drive(s: WalkerState, dt: number, actor: string): WalkInput | null {
    this.seen.set(actor, { x: s.x, z: s.z, at: this.now });
    let sess: Session | undefined;
    for (const c of this.sessions.values()) if (c.actor === actor) sess = c;
    if (!sess) return null;
    const def = this.defs.get(sess.id);
    if (!def) {
      this.sessions.delete(sess.id);
      return null;
    }
    sess.t += dt;
    if (sess.phase === "align") {
      const pose = interactPose(def);
      if (atPose(s, pose)) {
        if (sess.channel.fire(INTERACT_CLIP)) {
          sess.phase = "perform";
          sess.t = 0;
        } else {
          this.sessions.delete(sess.id);
          return null;
        }
        return ZERO_INPUT;
      }
      if (sess.t > INTERACT_ALIGN_TIMEOUT_S) {
        this.sessions.delete(sess.id);
        return null;
      }
      return alignInput(s, pose);
    }
    // perform: stand still; flip at the contact moment; finish when the clip ends
    if (!sess.flipped && sess.t >= this.contactS) {
      sess.flipped = true;
      this.setOn(sess.id, !this.isOn(sess.id));
    }
    const clipEnded = sess.channel.current !== INTERACT_CLIP && sess.t > 0.25;
    if (sess.t >= this.durationS || clipEnded) {
      // A clip cut short (another clip fired over it) before contact leaves the state alone.
      this.sessions.delete(sess.id);
      return ZERO_INPUT;
    }
    return ZERO_INPUT;
  }

  /** Once per frame: advance the clock and drop sessions whose actor vanished. */
  tick(dt: number): void {
    this.now += dt;
    for (const [id, sess] of [...this.sessions]) {
      const a = this.seen.get(sess.actor);
      if (!a || this.now - a.at > ACTOR_TTL) this.sessions.delete(id);
    }
  }

  /** Short status for the walk HUD, or null when there is nothing to say. */
  status(actor: string, at?: { x: number; z: number }): string | null {
    const sess = this.sessionOf(actor);
    if (sess) {
      const d = this.defs.get(sess.id);
      return sess.phase === "align" ? `${d?.label ?? "prop"} · stepping up…` : `${d?.label ?? "prop"} · using…`;
    }
    if (this.lastRefusal && this.now - this.lastRefusal.at < 4) return `${this.lastRefusal.id} · ${this.lastRefusal.reason}`;
    const p = at ?? this.seen.get(actor);
    const near = p ? this.nearest(p.x, p.z) : null;
    if (near) return `E · turn ${near.label.toLowerCase()} ${this.isOn(near.id) ? "off" : "on"}`;
    return null;
  }
}
